#include "EvaluationTestData.h"
#include <iostream>
#include <limits>
using namespace campusfix;
namespace {
int cases=0,checks=0;
void check(bool value,const char *message){if(!value)throw std::runtime_error(message);checks++;}
void scenario(const char *name){cases++;std::cout<<"CASE "<<name<<'\n';}
template<class F>void denied(SqliteConnection &db,int status,F fn){const auto before=test::dispatchFingerprint(db);bool rejected=false;try{fn();}catch(const WorkOrderError &e){rejected=e.status==status;}check(rejected,"expected rejection");check(before==test::dispatchFingerprint(db),"rejection no16table mutation");}
void set(SqliteConnection &db,const char *sql,std::int64_t id){auto q=db.prepare(sql);q.bindInt(1,id);q.step();}
std::int64_t ready(SqliteConnection &db,const test::ReadData &f){return test::completedOrder(db,f);}
struct SnapshotWrite {std::filesystem::path path;test::ReadAccount admin;std::int64_t id;bool attempted=false,ok=false;};
int concurrentClose(unsigned,void *value,void *statement,void *) {
    auto &c=*static_cast<SnapshotWrite *>(value);const char *sql=sqlite3_sql(static_cast<sqlite3_stmt *>(statement));
    if(!c.attempted&&sql&&std::string(sql).find("SELECT count(*) FROM work_orders")!=std::string::npos){c.attempted=true;try{SqliteConnection writer(c.path);EvaluationService(writer).close(c.admin.id,c.admin.token,c.id,7,{},"snapshot-other-connection");c.ok=true;}catch(const std::exception &){}}
    return 0;
}
}

int main(){initializeCrypto();const auto root=std::filesystem::temp_directory_path()/("campusfix-closable-"+newOpaqueId());std::filesystem::create_directories(root);int code=0;try{const auto path=root/"test.sqlite3";const auto f=test::taskFixture(path,CAMPUSFIX_MIGRATIONS_DIR,CAMPUSFIX_SEED_FILE);SqliteConnection db(path);const auto admin=f.accounts.at("demo_dispatcher"),sys=f.accounts.at("demo_sysadmin");const auto a=ready(db,f),b=ready(db,f),c=ready(db,f);
    const auto list=[&](const char *name,std::int64_t page=1,std::int64_t size=20){const auto actor=f.accounts.at(name);const auto before=test::dispatchFingerprint(db);SqliteConnection query(path);const auto p=EvaluationService(query).list(actor.id,actor.token,page,size);check(query.scalarInt("PRAGMA query_only")==1,"query only connection");check(before==test::dispatchFingerprint(db),"read all16 contents unchanged");return p;};
    scenario("AREA_SCOPE hierarchy paging overlap and stable ordering");auto p=list("demo_dispatcher",1,2);check(p.total==3&&p.items.size()==2,"page total consistent");auto all=list("demo_dispatcher");check(all.items.size()==3&&list("demo_dispatcher",2,2).items.size()==1&&list("demo_dispatcher",20).items.empty(),"pages and empty page");for(std::size_t i=1;i<all.items.size();i++)check(all.items[i-1].updatedAt>all.items[i].updatedAt||(all.items[i-1].updatedAt==all.items[i].updatedAt&&all.items[i-1].id>all.items[i].id),"stable updated DESC id DESC");test::grant(db,"demo_dispatcher","AREA_SCOPE",3);check(list("demo_dispatcher").total==3,"overlapping ancestor no duplicates");set(db,"UPDATE work_orders SET location_id=13 WHERE id=?1",c);check(list("demo_dispatcher").total==2,"cross scope hidden");
    scenario("CLOSE only independent from other capabilities and read permissions");for(const auto *cap:{"BUSINESS_READ","DISPATCH","REVIEW","INTERNAL_NOTE_READ"}){test::grant(db,"demo_sysadmin",cap,1);denied(db,403,[&]{list("demo_sysadmin");});}test::grant(db,"demo_sysadmin","CLOSE",1);test::revoke(db,"demo_sysadmin","BUSINESS_READ");check(list("demo_sysadmin").total==2,"CLOSE-only queue");denied(db,404,[&]{WorkOrderService(db).detail(sys.id,sys.token,a);});test::grant(db,"demo_sysadmin","CLOSE",3);check(list("demo_sysadmin").total==2,"CLOSE overlapping no duplication");test::revoke(db,"demo_sysadmin","CLOSE");denied(db,403,[&]{list("demo_sysadmin");});test::grant(db,"demo_sysadmin","CLOSE",{});check(list("demo_sysadmin").total==3,"global CLOSE sees both campuses");test::grant(db,"demo_sysadmin","BUSINESS_READ",1);check(list("demo_sysadmin").total==3,"read+close legal");
    scenario("invalid states timestamps and active assignment excluded, no heuristic qualification");for(const auto *value:{"NULL","'2026-02-30T00:00:00.000Z'","'not-a-date'","'2026-11-01T00:00:00+08:00'"}){db.execute(std::string("UPDATE work_orders SET completed_at=")+value+" WHERE id="+std::to_string(b));check(list("demo_dispatcher").total==1,"invalid completion not closable");}set(db,"UPDATE assignments SET ended_at=NULL,end_reason=NULL WHERE order_id=?1",a);check(list("demo_dispatcher").total==0,"active anomaly excluded");for(const auto *state:{"PENDING_VERIFY","IN_PROGRESS","CLOSED"}){db.execute(std::string("UPDATE work_orders SET status='")+state+"' WHERE id="+std::to_string(c));check(list("demo_sysadmin").total==0,"noncompleted omitted");}
    scenario("wrong roles revoked token disabled and pagination fail closed");for(const auto *name:{"demo_reporter01","demo_worker01"})denied(db,403,[&]{list(name);});for(const auto pair:{std::pair<std::int64_t,std::int64_t>{0,20},{1,101},{std::numeric_limits<std::int64_t>::max(),100}})denied(db,422,[&]{list("demo_dispatcher",pair.first,pair.second);});set(db,"UPDATE users SET status='DISABLED' WHERE id=?1",sys.id);denied(db,401,[&]{list("demo_sysadmin");});set(db,"UPDATE users SET status='ACTIVE' WHERE id=?1",sys.id);{auto q=db.prepare("UPDATE auth_sessions SET revoked_at='2026-11-01T00:00:00.000Z' WHERE token_hash=?1");q.bindText(1,tokenDigest(sys.token));q.step();}denied(db,401,[&]{list("demo_sysadmin");});test::integrity(db);std::cout<<"PASS closable cases="<<cases<<" assertions="<<checks<<'\n';
    scenario("WAL concurrent genuine close cannot split query count/items snapshot");db.execute("PRAGMA journal_mode=WAL");const auto x=ready(db,f);SnapshotWrite context{path,admin,x};SqliteConnection query(path);sqlite3_trace_v2(query.nativeHandle(),SQLITE_TRACE_STMT,concurrentClose,&context);const auto snapshot=EvaluationService(query).list(admin.id,admin.token);check(context.attempted&&context.ok,"other connection genuinely closed while reader snapshot active");check(snapshot.total==static_cast<std::int64_t>(snapshot.items.size()),"total and items from one snapshot");bool seen=false;for(const auto &item:snapshot.items)if(item.id==x)seen=true;check(seen,"old snapshot still includes originally completed row");bool nextSeen=false;for(const auto &item:list("demo_dispatcher").items)if(item.id==x)nextSeen=true;check(!nextSeen,"next request observes independent committed close");test::integrity(db);std::cout<<"FINAL closable cases="<<cases<<" assertions="<<checks<<'\n';
}catch(const std::exception &e){std::cerr<<"FAIL closable "<<e.what()<<'\n';code=1;}std::error_code ec;std::filesystem::remove_all(root,ec);return ec?1:code;}
